<template>
  <q-page class="game-page"><div class="shell">
    <header class="header"><div class="header-left"><q-btn flat round dense icon="arrow_back" @click="goBack"/><div class="icon"><q-icon name="edit_note"/></div><div><h1>Completa la frase</h1><p>Oculta una palabra o parte del texto y revela la respuesta cuando corresponda.</p></div></div><q-btn v-if="mode==='library'" unelevated no-caps icon="add" label="Nueva actividad" class="primary" @click="createActivity"/><div v-else-if="mode==='editor'" class="actions"><q-btn flat no-caps label="Cancelar" @click="mode='library'"/><q-btn unelevated no-caps icon="save" label="Guardar" class="primary" @click="saveActivity"/></div><div v-else class="actions"><q-badge color="positive">EN VIVO</q-badge><q-btn flat no-caps icon="close" label="Salir" @click="stopGame"/><q-btn unelevated no-caps icon="cast" label="Actualizar" class="primary" @click="sendLive"/></div></header>
    <section v-if="mode==='library'" class="library"><div v-if="!activities.length" class="empty"><q-icon name="edit_note" size="58px"/><h2>No hay actividades guardadas</h2><p>Crea frases con uno o varios espacios para completar.</p><q-btn unelevated no-caps icon="add" label="Crear actividad" class="primary" @click="createActivity"/></div><div v-else class="cards"><article v-for="a in activities" :key="a.id" class="card"><div class="card-icon"><q-icon name="edit_note"/></div><div class="copy"><h3>{{a.title}}</h3><span>{{a.rounds.length}} frases</span></div><q-btn flat round dense icon="edit" @click="editActivity(a)"/><q-btn flat round dense icon="delete_outline" color="red-4" @click="removeActivity(a)"/><q-btn unelevated no-caps icon="play_arrow" label="Abrir" class="primary" @click="playActivity(a)"/></article></div></section>
    <section v-else-if="mode==='editor'" class="editor"><aside><label>Nombre de la actividad</label><q-input v-model="title" dark outlined dense/><div class="round-head"><strong>Frases</strong><q-btn flat dense no-caps icon="add" label="Agregar" @click="addRound"/></div><button v-for="(r,i) in rounds" :key="r.id" class="round-row" :class="{active:r.id===activeId}" @click="activeId=r.id"><span>{{i+1}}</span><div><strong>{{r.prompt||'Sin frase'}}</strong><small>{{r.answer||'Sin respuesta'}}</small></div><q-btn v-if="rounds.length>1" flat round dense icon="close" @click.stop="deleteRound(r.id)"/></button></aside><main v-if="activeRound"><div class="field"><label>Frase incompleta</label><small>Usa ___ donde debe ir la respuesta.</small><q-input v-model="activeRound.prompt" dark outlined dense autogrow placeholder="El Señor es mi ___; nada me faltará"/></div><div class="field"><label>Respuesta correcta</label><q-input v-model="activeRound.answer" dark outlined dense placeholder="pastor"/></div><div class="field"><label>Referencia bíblica</label><q-input v-model="activeRound.bibleReference" dark outlined dense placeholder="Salmos 23:1"/></div><div class="field"><label>Explicación opcional</label><q-input v-model="activeRound.explanation" dark outlined dense autogrow/></div><div class="preview"><span>PREVISUALIZACIÓN</span><h2>{{activeRound.prompt||'Escribe la frase incompleta'}}</h2></div></main></section>
    <section v-else class="play"><aside><h2>{{playing?.title}}</h2><p>Frase {{playingIndex+1}} de {{playing?.rounds.length??0}}</p><button v-for="(r,i) in playing?.rounds??[]" :key="r.id" class="round-row" :class="{active:i===playingIndex}" @click="setRound(i)"><span>{{i+1}}</span><strong>{{r.bibleReference||`Frase ${i+1}`}}</strong></button></aside><main v-if="playingRound" class="stage"><div class="stage-card"><span>COMPLETA LA FRASE</span><h1>{{playingRound.prompt}}</h1><div v-if="showAnswer" class="answer"><span>RESPUESTA</span><strong>{{playingRound.answer}}</strong><small v-if="playingRound.explanation">{{playingRound.explanation}}</small></div><small class="reference">{{playingRound.bibleReference}}</small></div><div class="controls"><q-btn unelevated no-caps icon="visibility" label="Revelar respuesta" class="primary" @click="revealAnswer"/><q-btn flat no-caps icon="visibility_off" label="Ocultar respuesta" :disable="!showAnswer" @click="hideAnswer"/><q-space/><q-btn flat no-caps icon="arrow_upward" label="Anterior" :disable="playingIndex<=0" @click="move(-1)"/><q-btn unelevated no-caps icon-right="arrow_downward" label="Siguiente" class="primary" :disable="playingIndex>=(playing?.rounds.length??1)-1" @click="move(1)"/></div></main></section>
  </div></q-page>
</template>
<script setup lang="ts">
import{computed,onMounted,ref}from'vue';import{useQuasar}from'quasar';import{useRouter}from'vue-router';import{createBibleActivityId,deleteBibleActivity,getBibleActivities,saveBibleActivity}from'../services/bible-activity-library';import type{BibleActivityRecord,BibleActivityRound}from'../shared/bible-activities';
type Mode='library'|'editor'|'play';const router=useRouter(),$q=useQuasar();const mode=ref<Mode>('library'),activities=ref<BibleActivityRecord[]>([]),editingId=ref<string|null>(null),title=ref(''),rounds=ref<BibleActivityRound[]>([]),activeId=ref(''),playing=ref<BibleActivityRecord|null>(null),playingIndex=ref(0),showAnswer=ref(false);const activeRound=computed(()=>rounds.value.find(r=>r.id===activeId.value)??null),playingRound=computed(()=>playing.value?.rounds[playingIndex.value]??null);function fresh(){return{id:createBibleActivityId('complete-phrase-round'),prompt:'',answer:'',bibleReference:'',hint:'',explanation:''}}function reload(){activities.value=getBibleActivities('complete-phrase')}function goBack(){if(mode.value!=='library'){stopGame();mode.value='library';return}void router.push('/actividades')}function createActivity(){editingId.value=null;title.value='';rounds.value=[fresh()];activeId.value=rounds.value[0]!.id;mode.value='editor'}function editActivity(a:BibleActivityRecord){editingId.value=a.id;title.value=a.title;rounds.value=a.rounds.map(r=>({...r}));activeId.value=rounds.value[0]?.id??'';mode.value='editor'}function addRound(){const r=fresh();rounds.value.push(r);activeId.value=r.id}function deleteRound(id:string){rounds.value=rounds.value.filter(r=>r.id!==id);activeId.value=rounds.value[0]?.id??''}function saveActivity(){if(!title.value.trim()||rounds.value.some(r=>!r.prompt.includes('___')||!r.answer.trim())){$q.notify({type:'warning',message:'Cada frase debe incluir ___ y una respuesta correcta.',position:'top'});return}const now=new Date().toISOString(),old=editingId.value?activities.value.find(a=>a.id===editingId.value):null;saveBibleActivity({id:editingId.value??createBibleActivityId('complete-phrase'),type:'complete-phrase',title:title.value.trim(),rounds:rounds.value.map(r=>({...r,prompt:r.prompt.trim(),answer:r.answer.trim(),bibleReference:r.bibleReference.trim()})),createdAt:old?.createdAt??now,updatedAt:now});reload();mode.value='library'}function removeActivity(a:BibleActivityRecord){if(window.confirm(`¿Eliminar “${a.title}”?`)){deleteBibleActivity(a.id);reload()}}function playActivity(a:BibleActivityRecord){playing.value=a;playingIndex.value=0;showAnswer.value=false;mode.value='play';sendLive()}function setRound(i:number){playingIndex.value=i;showAnswer.value=false;sendLive()}function move(d:-1|1){const max=(playing.value?.rounds.length??1)-1;setRound(Math.min(max,Math.max(0,playingIndex.value+d)))}function revealAnswer(){showAnswer.value=true;sendLive()}function hideAnswer(){showAnswer.value=false;sendLive()}function stopGame(){if(mode.value==='play')window.icpStudio?.projection.setState({mode:'blank'});playing.value=null}function sendLive(){const r=playingRound.value;if(!r||!playing.value)return;window.icpStudio?.projection.setState({mode:'content',title:playing.value.title,body:`${r.prompt}${showAnswer.value?`\n\nRespuesta: ${r.answer}`:''}`,footer:r.bibleReference})}onMounted(reload);
</script>
<style scoped>
