.stage-card>span{color:#f472b6;font-size:9px;letter-spacing:.1em}.stage-card h1{font-size:clamp(28px,4vw,54px);line-height:1.2}.answer{display:flex;flex-direction:column;margin-top:24px;padding:18px;background:#ec489912;border:1px solid #f472b655;border-radius:10px}.answer span{color:#f9a8d4;font-size:9px}.answer strong{font-size:28px}.reference{display:block;margin-top:18px;color:#94a3b8}.controls{gap:8px;margin-top:12px}@media(max-width:850px){.editor,.play{grid-template-columns:1fr}}
</style>